import{_ as t,o as a,c as r,a5 as d}from"./chunks/framework.a5no_H3L.js";const w=JSON.parse('{"title":"DLL 加载与 Windows API","description":"程序几乎不可能不调用系统功能——读写文件、分配内存、显示窗口、联网。这些功能由 Windows 以 DLL 和 API 的形式提供。这一章讲 DLL 的加载方式，以及逆向中最常打交道的几类 Windows API。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"reverse-engineering/03-windows-internals/chapter-03-dll-api.md","filePath":"reverse-engineering/03-windows-internals/chapter-03-dll-api.md"}'),i={name:"reverse-engineering/03-windows-internals/chapter-03-dll-api.md"};function n(l,e,s,c,o,p){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="dll-加载与-windows-api" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">DLL 加载与 Windows API <a class="header-anchor" href="#dll-加载与-windows-api" aria-label="Permalink to &quot;DLL 加载与 Windows API&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">程序几乎不可能不调用系统功能——读写文件、分配内存、显示窗口、联网。这些功能由 Windows 以 DLL 和 API 的形式提供。这一章讲 DLL 的加载方式，以及逆向中最常打交道的几类 Windows API。</p><h2 id="_1-静态链接与动态链接" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">1. 静态链接与动态链接 <a class="header-anchor" href="#_1-静态链接与动态链接" aria-label="Permalink to &quot;1. 静态链接与动态链接&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">程序要使用外部代码，有两种方式：</p><ul data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><li data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><strong>静态链接</strong>：把外部代码直接复制进最终的可执行文件。文件大，但运行时不依赖外部库。</li><li data-src-line="11" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><strong>动态链接</strong>：可执行文件里只记录「我需要哪个 DLL 的哪个函数」，运行时由系统把 DLL 加载进来、解析地址。Windows 上 <code>.exe</code> 几乎都动态链接系统 DLL。</li></ul><p data-src-line="13" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">动态链接的好处是共享：所有程序共用一份 <code>kernel32.dll</code>，不用各自复制一份。代价是运行时需要解析——这正是 PE 导入表存在的原因。</p><h2 id="_2-隐式链接与显式链接" tabindex="-1" data-src-line="15" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">2. 隐式链接与显式链接 <a class="header-anchor" href="#_2-隐式链接与显式链接" aria-label="Permalink to &quot;2. 隐式链接与显式链接&quot;">​</a></h2><p data-src-line="17" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">动态链接又分两种：</p><p data-src-line="19" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><strong>隐式链接</strong>：程序在 PE 导入表里声明依赖，加载器在程序启动时自动加载 DLL、填充 IAT。这是最常见的用法，也是静态分析时看导入表能直接看到的依赖。</p><p data-src-line="21" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><strong>显式链接</strong>：程序在运行时调用 <code>LoadLibrary</code> 加载 DLL、用 <code>GetProcAddress</code> 按函数名查地址。这种依赖<strong>不写在导入表里</strong>，静态分析看不到。</p><p data-src-line="23" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">两者的区别对逆向很重要：</p><ul data-src-line="25" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><li data-src-line="25" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">隐式链接的函数，反汇编器直接标出名字（<code>call kernel32!CreateFileW</code>）。</li><li data-src-line="26" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">显式链接的函数，反汇编里只能看到 <code>LoadLibrary</code> 和 <code>GetProcAddress</code> 的调用，真实调用的函数名被藏起来了。这是很多恶意软件和加壳程序隐藏行为的手段。</li></ul><h2 id="_3-核心-dll-与-api-层次" tabindex="-1" data-src-line="28" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">3. 核心 DLL 与 API 层次 <a class="header-anchor" href="#_3-核心-dll-与-api-层次" aria-label="Permalink to &quot;3. 核心 DLL 与 API 层次&quot;">​</a></h2><p data-src-line="30" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">Windows 的功能按层次组织，逆向中常遇到这几层：</p><table tabindex="0"><thead data-src-line="32" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><tr data-src-line="32" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><th style="text-align:left;">DLL</th><th style="text-align:left;">定位</th><th style="text-align:left;">常见函数</th></tr></thead><tbody data-src-line="34" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><tr data-src-line="34" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>ntdll.dll</code></td><td style="text-align:left;">最底层，直接对接内核</td><td style="text-align:left;"><code>NtCreateFile</code>、<code>NtQueryInformationProcess</code></td></tr><tr data-src-line="35" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>kernel32.dll</code></td><td style="text-align:left;">基础 API，进程/内存/文件/线程</td><td style="text-align:left;"><code>CreateFileW</code>、<code>VirtualAlloc</code>、<code>WriteFile</code></td></tr><tr data-src-line="36" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>user32.dll</code></td><td style="text-align:left;">用户界面</td><td style="text-align:left;"><code>MessageBoxW</code>、<code>CreateWindowExW</code></td></tr><tr data-src-line="37" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>ws2_32.dll</code></td><td style="text-align:left;">网络（Winsock）</td><td style="text-align:left;"><code>socket</code>、<code>connect</code>、<code>send</code>、<code>recv</code></td></tr><tr data-src-line="38" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>advapi32.dll</code></td><td style="text-align:left;">注册表、服务</td><td style="text-align:left;"><code>RegOpenKeyExW</code>、<code>RegSetValueExW</code></td></tr></tbody></table><p data-src-line="40" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">一个典型的调用链：程序调用 <code>kernel32.CreateFileW</code>，它内部转调 <code>ntdll.NtCreateFile</code>，再进入内核。逆向用户态程序时，你主要和 <code>kernel32</code>、<code>user32</code>、<code>ws2_32</code> 这些层打交道。</p><h2 id="_4-从-api-反推程序行为" tabindex="-1" data-src-line="42" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">4. 从 API 反推程序行为 <a class="header-anchor" href="#_4-从-api-反推程序行为" aria-label="Permalink to &quot;4. 从 API 反推程序行为&quot;">​</a></h2><p data-src-line="44" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">理解了 API 的层次和分类，就拿到了逆向的「速查表」：看到某个 API 调用，就能推断程序在做什么。</p><table tabindex="0"><thead data-src-line="46" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><tr data-src-line="46" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><th style="text-align:left;">导入的 API</th><th style="text-align:left;">推断的行为</th></tr></thead><tbody data-src-line="48" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><tr data-src-line="48" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>CreateFileW</code> + <code>WriteFile</code></td><td style="text-align:left;">读写文件</td></tr><tr data-src-line="49" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>RegOpenKeyExW</code> + <code>RegSetValueExW</code></td><td style="text-align:left;">操作注册表</td></tr><tr data-src-line="50" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>socket</code> + <code>connect</code> + <code>send</code>/<code>recv</code></td><td style="text-align:left;">网络通信</td></tr><tr data-src-line="51" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>VirtualAlloc</code> + <code>VirtualProtect</code></td><td style="text-align:left;">动态分配/修改内存权限（常与壳、注入有关）</td></tr><tr data-src-line="52" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>CreateRemoteThread</code> + <code>WriteProcessMemory</code></td><td style="text-align:left;">进程注入（修改其他进程）</td></tr><tr data-src-line="53" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><td style="text-align:left;"><code>GetProcAddress</code> + <code>LoadLibrary</code></td><td style="text-align:left;">动态解析函数（隐藏真实调用）</td></tr></tbody></table><p data-src-line="55" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">静态分析的第一步，往往就是扫一眼导入表，用这张「API 速查表」对程序行为形成初步假设。具体的分析流程在<a href="./../05-static-analysis/chapter-01-basics.html">静态分析</a>展开。</p><hr><blockquote data-src-line="59" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md"><p data-src-line="59" data-src-file="reverse-engineering/03-windows-internals/chapter-03-dll-api.md">本章建立的是 DLL 与 API 的图景：动态链接让程序依赖系统 DLL，隐式链接写在导入表里、显式链接藏在运行时；看 API 就能反推程序行为。至此 Windows 底层机制完整。下一阶段进入<a href="./../05-static-analysis/chapter-01-basics.html">静态分析</a>。</p></blockquote>',22)])])}const h=t(i,[["render",n]]);export{w as __pageData,h as default};
